  --color-primary-hover: #4338ca;
  --color-primary-active: #3730a3;
  --color-text: #111827;
  --color-text-muted: #6b7280;
  --color-border: #d1d5db;
  --color-border-focus: #4f46e5;
  --color-error: #b91c1c;
  --color-error-bg: #fef2f2;
  --color-error-border: #fca5a5;
  --color-success: #166534;
  --color-success-bg: #f0fdf4;
  --color-success-border: #86efac;
  --color-link: #4f46e5;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.08);
  --transition-fast: 150ms ease;
}

/* ============================================================
   Reset & base
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 1.5rem;
}

/* ============================================================
   Skip link
   ============================================================ */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: 1rem;
}

/* ============================================================
   Card
   ============================================================ */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 480px;
}

.card__header {
  margin-bottom: 2rem;
}

.card__title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
  margin-bottom: 0.375rem;
}

.card__subtitle {
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

/* ============================================================
   Status message (live region)
   ============================================================ */
.status-message:not(:empty) {
  border-radius: var(--radius-sm);
  padding: 0.75rem 1rem;
  font-size: 0.9375rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}

.status-message.is-success {
  background: var(--color-success-bg);
  border: 1px solid var(--color-success-border);
  color: var(--color-success);
}

/* ============================================================
   Form field
   ============================================================ */
.form-field {
  margin-bottom: 0.75rem;
}

/* ============================================================
   Checkbox
   ============================================================ */
.checkbox-wrapper {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.checkbox-wrapper input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  cursor: pointer;
  margin-top: 0.15rem;
  transition: border-color var(--transition-fast), background-color var(--transition-fast);
  position: relative;
}

.checkbox-wrapper input[type="checkbox"]:hover {
  border-color: var(--color-primary);
}

.checkbox-wrapper input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

.checkbox-wrapper input[type="checkbox"]:checked {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
}

.checkbox-wrapper input[type="checkbox"]:checked::after {
  content: "";
  display: block;
  position: absolute;
  top: 1px;
  left: 4px;
  width: 6px;
  height: 10px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

.checkbox-wrapper input[type="checkbox"][aria-invalid="true"] {
  border-color: var(--color-error);
}

.checkbox-wrapper label {
  cursor: pointer;
  font-size: 0.9375rem;
  color: var(--color-text);
  line-height: 1.55;
}

.required-star {
  color: var(--color-error);
  margin-left: 0.125rem;
  font-weight: 700;
}

.terms-link {
  color: var(--color-link);
  text-underline-offset: 2px;
}

.terms-link:hover {
  color: var(--color-primary-hover);
}

.terms-link:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ============================================================
   Helper & error text
   ============================================================ */
.helper-text {
  margin-top: 0.5rem;
  margin-left: 2rem; /* align with label */
  font-size: 0.875rem;
  color: var(--color-text-muted);
}

.error-text {
  margin-top: 0.5rem;
  margin-left: 2rem;
  font-size: 0.875rem;
  color: var(--color-error);
  font-weight: 500;
}

/* ============================================================
   Required note
   ============================================================ */
.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.75rem;
}

/* ============================================================
   Submit button
   ============================================================ */
.btn-submit {
  display: block;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background-color: var(--color-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition-fast), transform var(--transition-fast);
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background-color: var(--color-primary-hover);
}

.btn-submit:active {
  background-color: var(--color-primary-active);
  transform: scale(0.99);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ============================================================
   Invalid field highlight
   ============================================================ */
.form-field.is-invalid .checkbox-wrapper {
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  border-radius: var(--radius-sm);
  padding: 0.625rem 0.75rem;
  margin: -0.625rem -0.75rem;
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 1ms !important;
    animation-duration: 1ms !important;
  }
}

/* ============================================================
   Forced colors (Windows high contrast)
   ============================================================ */
@media (forced-colors: active) {
  .checkbox-wrapper input[type="checkbox"] {
    border: 2px solid ButtonText;
    background: Field;
    forced-color-adjust: none;
  }

  .checkbox-wrapper input[type="checkbox"]:checked {
    background: Highlight;
    border-color: Highlight;
  }

  .checkbox-wrapper input[type="checkbox"]:checked::after {
    border-color: HighlightText;
  }

  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
    forced-color-adjust: none;
  }
}

/* ============================================================
   Narrow viewport / reflow (320 px)
   ============================================================ */
@media (max-width: 360px) {
  .card {
    padding: 1.5rem 1rem;
  }

  .card__title {
    font-size: 1.25rem;
  }
}
