    <main id="main">
      <div class="card">
        <header class="card__header">
          <h1 class="card__title">Terms of Use</h1>
          <p class="card__subtitle">Please review and accept our terms before continuing.</p>
        </header>

        <div aria-live="polite" aria-atomic="true" class="status-message" id="status-message"></div>

        <form id="consent-form" novalidate>
          <div class="form-field">
            <div class="checkbox-wrapper">
              <input
                type="checkbox"
                id="agree-terms"
                name="agree-terms"
                required
                aria-describedby="agree-help agree-error"
              />
              <label for="agree-terms">
                I agree to the
                <a href="#terms-modal" class="terms-link" aria-haspopup="dialog">Terms of Use</a>
                and
                <a href="#privacy-modal" class="terms-link" aria-haspopup="dialog">Privacy Policy</a>
                <span aria-hidden="true" class="required-star">*</span>
              </label>
            </div>
            <p id="agree-help" class="helper-text">
              You must accept the terms to create an account and use our service.
            </p>
            <p id="agree-error" class="error-text" hidden>
              Error: You must agree to the Terms of Use and Privacy Policy to continue.
            </p>
          </div>

          <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

          <button type="submit" class="btn-submit">Agree and continue</button>
        </form>
      </div>
