  const form = document.getElementById("consent-form");
  const checkbox = document.getElementById("agree-terms");
  const errorEl = document.getElementById("agree-error");
  const statusMessage = document.getElementById("status-message");
  const formField = checkbox.closest(".form-field");

  function setInvalid() {
    checkbox.setAttribute("aria-invalid", "true");
    errorEl.hidden = false;
    formField.classList.add("is-invalid");
  }

  function clearInvalid() {
    checkbox.removeAttribute("aria-invalid");
    errorEl.hidden = true;
    formField.classList.remove("is-invalid");
  }

  // Clear error as soon as the user checks the box
  checkbox.addEventListener("change", function () {
    if (checkbox.checked) {
      clearInvalid();
    }
  });

  form.addEventListener("submit", function (event) {
    event.preventDefault();

    statusMessage.textContent = "";
    statusMessage.className = "status-message";

    if (!checkbox.checked) {
      setInvalid();
      checkbox.focus();
      return;
    }

    clearInvalid();

    // Success
    statusMessage.textContent = "✓ You have agreed to the Terms of Use. Welcome!";
    statusMessage.classList.add("is-success");

    // Optionally: form.submit() here for a real submission
  });
})();
